package io.knowledgebrain.space;
import io.knowledgebrain.contracts.space.groupprogresspolicy.v1.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP",matches=".+")
class GroupProgressPolicyKafkaIntegrationTest {
 @Test void enrollmentCdcBytesAndUnacknowledgedReplay()throws Exception{
  var test=new GroupProgressPolicyIntegrationTest();test.setup();var f=test.f;var v=test.change(0,"OWNER_SUMMARY");test.change(1,"DISABLED");test.change(2,"OWNER_SUMMARY");var expected=new HashMap<String,byte[]>();for(var bytes:f.jdbc.queryForList("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.policyId())){var e=GroupProgressPolicyEnvelopeV1.parseFrom(bytes);expected.put(e.getEventId(),bytes);}assertEquals(3,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP"));options.put("group.id","group-validation-"+UUID.randomUUID());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.keystore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/group-kafka-test/ca.crt")));options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/group-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/group-kafka-test/user.key")));
  for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("space.group-progress-policy.v1"));long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<3&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=GroupProgressPolicyEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),record.value());assertEquals(e.getAggregateId(),record.key());assertEquals(f.trace,e.getTraceId());assertEquals(test.space.toString(),e.getSpaceId());assertEquals("GroupProgressPolicy",e.getAggregateType());var p=GroupProgressPolicySnapshotV1.parseFrom(e.getPayload());assertEquals(v.policyId().toString(),p.getPolicyId());assertEquals("OWNER",p.getAudience());for(var entry:Map.of("trace_id",f.trace,"schema_group","space","schema_artifact","group-progress-policy-events","schema_version","1").entrySet())assertEquals(entry.getValue(),new String(record.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));seen.add(e.getEventId());}}assertEquals(expected.keySet(),seen);}
  System.out.println("PASS space.group-progress-policy.v1 three byte-exact Course progress snapshots, stable IDs, trace/schema headers and unacknowledged replay");
 }
}
